export const marketStates = Object.keys(marketLocations);
const key = s => s.toLowerCase().replace(/ district$/i, '').replace(/[^a-z0-9]/g, '');
const aliases = {"chattisgarh":"chhattisgarh","keralam":"kerala","nctofdelhi":"delhi","pondicherry":"puducherry","andamanandnicobar":"andamanandnicobarislands","dadraandnagarhaveli":"dadraandnagarhavelianddamananddiu","damananddiu":"dadraandnagarhavelianddamananddiu","rangareddi":"rangareddy","mahabubnagar":"mahbubnagar","mahaboobnagar":"mahbubnagar","vizianagaram":"vijayanagaram","hanumakonda":"hanamkonda","jagitial":"jagtial","jangoan":"jangaon","jayashankarbhupalapally":"bhupalapally","kumurambheemasifabad":"asifabad","rajannasircilla":"rajannasiricilla"};
export function matchMarketLocation(state = '', district = '') {
  const normalized = s => aliases[key(s)] || key(s);
  const selectedState = marketStates.find(s => normalized(s) === normalized(state)) || '';
  return { state: selectedState, district: (marketLocations[selectedState] || []).find(d => normalized(d) === normalized(district)) || '' };
}
